parameters.jsCode:
const body = $json.body || {};
const entry = body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const contact = change?.contacts?.[0];
const msg = change?.messages?.[0];

if (!msg) {
  return [];
}

return [{
  json: {
    senderContact: msg.from || 'Unknown',
    senderName: contact?.profile?.name || 'WhatsApp Client',
    subject: 'WhatsApp Inbound Message',
    messageText: msg.text?.body || '[Attachment or Media]',
    messageId: msg.id,
    channel: 'WHATSAPP',
    timestamp: new Date().toISOString()
  }
}];

return [{
  json: {
    senderContact: $json.from?.value?.[0]?.address || $json.from?.text || 'email@client.com',
    senderName: $json.from?.value?.[0]?.name || 'Email Client',
    subject: $json.subject || 'New Inquiry',
    messageText: $json.snippet || $json.textPlain || '',
    threadId: $json.threadId || '',
    channel: 'GMAIL',
    timestamp: new Date().toISOString()
  }
}];

parameters.text:
=Analyze the following customer inquiry and return JSON:
Channel: {{ $json.channel }}
Client: {{ $json.senderName }} ({{ $json.senderContact }})
Subject: {{ $json.subject }}
Message: {{ $json.messageText }}

Format required:
{
  "intent": "SALES | SUPPORT | URGENT_QUOTE | GENERAL",
  "priority": "HIGH | MEDIUM | LOW",
  "summary": "1 short sentence",
  "draftReply": "professional response"
}

